from pathlib import Path
import re,base64,hashlib,json
r=Path(__file__).resolve().parent;source=r.parent
html=(source/'kalkulacka-priplatku-za-smeny.html').read_text()
core=re.search(r'<body[^>]*>([\s\S]*?)</body>',html).group(1)
core=re.sub(r'<script\b[^>]*>[\s\S]*?</script>','',core)
core=re.sub(r'<img\b[^>]*>','',core)
js=(source/'priplatky-smeny.js').read_text();idx=js.rfind('})();');js=js[:idx]+(r/'bridge.js').read_text()+js[idx:]
logo='data:image/svg+xml;base64,'+base64.b64encode((source/'logo-rv-v32.svg').read_bytes()).decode()
ui=(r/'ui.js').read_text().replace("const v=id=>E.snapshot().values[id];", "const v=id=>{let s=E.snapshot().values[id];if(id==='shiftDate'&&/^\\d{1,2}\\./.test(s)){const a=s.match(/(\\d+)\\.\\s*(\\d+)\\.\\s*(\\d+)/);s=a[3]+'-'+a[2].padStart(2,'0')+'-'+a[1].padStart(2,'0')}return s};")
for mode,title in [('a','A — Směna na první pohled'),('b','B — Nejdřív váš úkol')]:
 css=(r/'common.css').read_text()+(r/f'{mode}.css').read_text()
 rail='''<aside class="rail"><span class="eyebrow">Pracovní prostor</span><button data-nav="home"><span>⌂</span> Vybrat úkol</button><button data-nav="shift"><span>01</span> Směna</button><button data-nav="month"><span>02</span> Měsíc</button><button data-nav="audit"><span>03</span> Výplatnice</button><div class="rail-note">RYCHLÉVÝPOČTY.CZ<br>Vaše údaje.<br>Vaše zařízení.</div></aside>''' if mode=='b' else ''
 nav='''<button data-nav="shift">Směna</button><button data-nav="month">Měsíc</button><button data-nav="audit">Páska</button>''' if mode=='a' else '<button data-nav="home">Pracovní prostor</button>'
 out=f'''<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · RychléVýpočty.cz</title><link rel="canonical" href="https://rychlevypocty.cz/kalkulacka-priplatku-za-smeny.html"><style>{css}</style></head><body data-concept="{mode}"><div id="core" hidden aria-hidden="true">{core}</div><a class="skip" href="#surface">Přejít k nástroji</a><div class="wrap"><header class="topbar"><a class="brand" href="https://rychlevypocty.cz/" aria-label="RychléVýpočty.cz – domů"><img src="{logo}" alt="RychléVýpočty.cz" width="218" height="40"></a><div class="toplinks">{nav}<button data-nav="guide">Průvodce ↗</button></div><span class="prototype">KONCEPT {mode.upper()} / NÁVRH</span></header><nav class="mobile-nav" aria-label="Pracovní prostor"><button data-nav="shift">Směna</button><button data-nav="month">Měsíc</button><button data-nav="audit">Páska</button></nav><div class="{'shell-b' if mode=='b' else 'shell-a'}">{rail}<main id="surface" tabindex="-1"></main></div><p id="x-toast" class="message" role="status" hidden></p><footer class="foot"><span>RychléVýpočty.cz · jasné odpovědi na každodenní otázky</span><span><a href="https://rychlevypocty.cz/mzdy-a-prace.html">Mzdy a práce</a><a href="https://rychlevypocty.cz/">Všechny kalkulačky</a></span></footer></div><div id="mobile-live" class="mobile-total" hidden></div><input id="x-import-file" type="file" accept=".json,application/json" hidden><template id="guide-template">{(r/'guide.html').read_text()}</template><script>{js}</script><script>{ui}</script></body></html>'''
 (r/'dist'/f'koncept-{mode}.html').write_text(out)
(r/'dist'/'index.html').write_text('''<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>PR52 — dva směry</title><style>body{font:18px system-ui;background:#f6f7f2;color:#102e37;max-width:1000px;margin:70px auto;padding:24px}h1{font-size:48px;letter-spacing:-.05em}main{display:grid;grid-template-columns:1fr 1fr;gap:24px}a{display:block;padding:32px;color:inherit;background:white;border:1px solid #d8dfda;border-radius:16px;text-decoration:none}h2{font-size:28px}p{line-height:1.6}@media(max-width:650px){main{grid-template-columns:1fr}h1{font-size:36px}}</style><h1>Stejný výpočet.<br>Dvě odlišné cesty.</h1><p>Funkční návrhy pro výběr směru PR #52. Otevřete na mobilu i na počítači.</p><main><a href="koncept-a.html"><small>KONCEPT A</small><h2>Směna na první pohled ↗</h2><p>Přímé zadání, živá částka a grafický rozpad. Měsíc a páska přicházejí až podle potřeby.</p></a><a href="koncept-b.html"><small>KONCEPT B</small><h2>Nejdřív váš úkol ↗</h2><p>Výběr cíle, vedená směna a měsíční kalendář. Jeden úkol, jedno soustředěné prostředí.</p></a></main><p>Ukázka: 11. 12. 2026, 22–06, pauza 02:00–02:30, mzda a PHV 200 Kč/h → příplatky 260 Kč. Data se nikam neodesílají.</p>''')
(r/'core-sha256.txt').write_text(hashlib.sha256((source/'priplatky-smeny.js').read_bytes()).hexdigest()+'  source priplatky-smeny.js\n')
print('Built A/B; calculation source SHA256:',(r/'core-sha256.txt').read_text())
